2. Interactive SVG/Canvas Preview
In addition to rendered .mp4 video files, this website renders live vector graphics directly inside the browser using HTML5 Canvas and SVG:


Code
viewof speed = Inputs.range([0.2, 3.0], {value: 1.0, step: 0.1, label: "Animation Speed"})









Code
manimCanvas = {
  const width = 500;
  const height = 280;
  const ctx = DOM.context2d(width, height);
  let t = 0;

  function draw() {
    t += 0.03 * speed;
    ctx.fillStyle = "#111827";
    ctx.fillRect(0, 0, width, height);

    const cx = width / 2;
    const cy = 40;
    const l1 = 80;
    const l2 = 70;

    const th1 = Math.sin(t) * 1.2;
    const th2 = Math.sin(t * 1.4 + 0.5) * 1.5;

    const x1 = cx + l1 * Math.sin(th1);
    const y1 = cy + l1 * Math.cos(th1);

    const x2 = x1 + l2 * Math.sin(th2);
    const y2 = y1 + l2 * Math.cos(th2);

    // Grid lines
    ctx.strokeStyle = "rgba(255,255,255,0.05)";
    for (let x = 0; x &lt; width; x += 40) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, height); ctx.stroke();
    }

    // Rods
    ctx.strokeStyle = "#60a5fa";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(cx, cy); ctx.lineTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.stroke();

    // Bobs
    ctx.fillStyle = "#38bdf8";
    ctx.beginPath(); ctx.arc(x1, y1, 8, 0, 2*Math.PI); ctx.fill();

    ctx.fillStyle = "#f43f5e";
    ctx.beginPath(); ctx.arc(x2, y2, 10, 0, 2*Math.PI); ctx.fill();

    ctx.fillStyle = "#94a3b8";
    ctx.font = "12px monospace";
    ctx.fillText("Interactive Canvas Preview (Simulated Manim Frame)", 20, height - 15);
  }

  const interval = d3.interval(draw, 25);
  invalidation.then(() =&gt; interval.stop());
  return ctx.canvas;
}

Quarto allows client-side interactive simulations using Observable JS ({ojs}). The simulation runs entirely within your browser via HTML5 Canvas—no Python or server backend required!
Use the sliders below to adjust the physical parameters and observe the real-time dynamics:


Code
viewof length = Inputs.range([0.5, 3.0], {value: 1.5, step: 0.1, label: "Pendulum Length (m)"})
viewof gravity = Inputs.range([1.0, 25.0], {value: 9.81, step: 0.1, label: "Gravity g (m/s²)"})
viewof damping = Inputs.range([0.0, 0.5], {value: 0.05, step: 0.01, label: "Damping Factor γ"})
viewof initialAngle = Inputs.range([-170, 170], {value: 60, step: 5, label: "Initial Angle θ₀ (deg)"})
































Code
canvas = {
  const width = 600;
  const height = 350;
  const ctx = DOM.context2d(width, height);

  let theta = initialAngle * Math.PI / 180;
  let omega = 0.0;
  let dt = 0.02;
  const originX = width / 2;
  const originY = 50;
  const scale = 80;

  function step() {
    // Non-linear pendulum: d²θ/dt² = -(g/L) sin(θ) - γ dθ/dt
    const alpha = -(gravity / length) * Math.sin(theta) - damping * omega;
    omega += alpha * dt;
    theta += omega * dt;

    ctx.clearRect(0, 0, width, height);

    // Pivot support
    ctx.fillStyle = "#333";
    ctx.fillRect(originX - 40, originY - 10, 80, 10);

    const bobX = originX + length * scale * Math.sin(theta);
    const bobY = originY + length * scale * Math.cos(theta);

    // Rod
    ctx.beginPath();
    ctx.moveTo(originX, originY);
    ctx.lineTo(bobX, bobY);
    ctx.strokeStyle = "#4f46e5";
    ctx.lineWidth = 3;
    ctx.stroke();

    // Pivot pin
    ctx.beginPath();
    ctx.arc(originX, originY, 5, 0, 2 * Math.PI);
    ctx.fillStyle = "#1e293b";
    ctx.fill();

    // Bob
    ctx.beginPath();
    ctx.arc(bobX, bobY, 18, 0, 2 * Math.PI);
    ctx.fillStyle = "#ef4444";
    ctx.shadowColor = "rgba(0,0,0,0.3)";
    ctx.shadowBlur = 8;
    ctx.fill();
    ctx.shadowBlur = 0;

    // Display telemetry
    ctx.fillStyle = "#0f172a";
    ctx.font = "14px monospace";
    ctx.fillText(`θ: ${(theta * 180 / Math.PI).toFixed(1)}°`, 20, 30);
    ctx.fillText(`ω: ${omega.toFixed(2)} rad/s`, 20, 50);
    ctx.fillText(`E_mech: ${(0.5 * length * length * omega * omega + gravity * length * (1 - Math.cos(theta))).toFixed(2)} J/kg`, 20, 70);
  }

  const timer = d3.interval(step, 20);
  invalidation.then(() =&gt; timer.stop());

  return ctx.canvas;
}

